-- Mount Hyjal: isi zona 616 yang tidak ada di dump SFDB.
--
-- Latar belakang
--   Rantai quest Hyjal buntu bukan karena bug core, tapi karena world DB kita
--   berasal dari dump SFDB yang tidak punya satu pun spawn di zona itu. Pemain
--   yang sampai ke Nordrassil menemukan zona kosong. File ini mengisinya
--   dengan data spawn dari dump world TrinityCore 4.3.4, diterjemahkan ke
--   skema SkyFire 5.4.8. Konten Hyjal di client 5.4.8 sama dengan Cataclysm,
--   jadi entry, koordinat dan quest-nya cocok.
--
-- Dibuat oleh tools/dev/port_hyjal_spawns.py -- jangan diedit tangan, ubah
-- skripnya lalu bangkitkan ulang.
--
-- Keputusan yang perlu diketahui saat membaca file ini
--   * Semua spawn dipasang di `phaseid` 0 supaya terlihat semua pemain. Phasing
--     asli Hyjal digerakkan script C++ yang tidak ada di SkyFire; kalau phaseid
--     disalin apa adanya, zonanya tetap kosong di mata pemain. Harganya: versi
--     berbeda dari area yang sama tampil bersamaan.
--   * Karena itu spawn di-dedupe pada radius 3.0 yard per entry, dan baris
--     fase dasar (169) yang dimenangkan.
--   * Template hanya diisi untuk entry yang belum ada (INSERT IGNORE). Baris
--     SFDB yang sudah benar tidak pernah ditimpa.
--   * `AIName` dan `ScriptName` dikosongkan pada template hasil port: baris
--     smart_scripts dan script C++ yang dirujuk nama-nama itu tidak ada di sini.
--   * `MovementType` 2 (waypoint) diturunkan ke 0 karena `waypoint_data` tidak
--     ikut diport.
--
-- Idempotent: rentang guid milik file ini dihapus dulu, lalu diisi ulang.
--   creature   8400001-8404000
--   gameobject 8400001-8401000
--
-- Sumber: TDB_full_world_434.22011_2022_01_09.sql
-- Isi: 3675 creature, 864 gameobject, 319 creature_template, 137 gameobject_template.

DELETE FROM `creature` WHERE `guid` BETWEEN 8400001 AND 8404000;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 8400001 AND 8401000;

-- ---------------------------------------------------------------------------
-- Template yang belum ada di SFDB
-- ---------------------------------------------------------------------------

-- Daftar entry yang benar-benar baru dicatat dulu, sebelum INSERT IGNORE di
-- bawah menutup bedanya. Backfill damage nanti hanya boleh menyentuh entry
-- di daftar ini, jangan sampai baris SFDB yang kebetulan bermindmg 0 ikut
-- tertimpa.
DROP TABLE IF EXISTS `prabowow_hyjal_new_templates`;
CREATE TABLE `prabowow_hyjal_new_templates` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY);

DELETE FROM `prabowow_hyjal_new_templates`
WHERE `entry` IN (SELECT `entry` FROM `creature_template`);


-- Damage: kolom mindmg/maxdmg/attackpower tidak ada di skema 4.3.4, tapi
-- Creature::SelectLevel memakainya apa adanya. Template baru di atas masuk
-- dengan nilai 0, lalu diisi rata-rata template yang sudah ada di DB pada
-- minlevel dan rank yang sama. Kalau tidak ada pembanding, dipakai rata-rata
-- level terdekat.
DROP TABLE IF EXISTS `prabowow_hyjal_dmg_ref`;
CREATE TABLE `prabowow_hyjal_dmg_ref` AS
    SELECT `minlevel`, `npc_rank`, AVG(`mindmg`) AS `mindmg`,
           AVG(`maxdmg`) AS `maxdmg`, AVG(`attackpower`) AS `attackpower`
    FROM `creature_template`
    WHERE `mindmg` > 0
      AND `entry` NOT IN (SELECT `entry` FROM `prabowow_hyjal_new_templates`)
    GROUP BY `minlevel`, `npc_rank`;

UPDATE `creature_template` `ct`
JOIN `prabowow_hyjal_new_templates` `new` ON `new`.`entry` = `ct`.`entry`
JOIN `prabowow_hyjal_dmg_ref` `ref`
  ON `ref`.`minlevel` = `ct`.`minlevel` AND `ref`.`npc_rank` = `ct`.`npc_rank`
SET `ct`.`mindmg` = `ref`.`mindmg`,
    `ct`.`maxdmg` = `ref`.`maxdmg`,
    `ct`.`attackpower` = `ref`.`attackpower`;

-- Sisanya (kombinasi level/rank tanpa pembanding persis) memakai level
-- terdekat. Satu UPDATE per kolom karena MySQL cuma boleh menyebut tabel
-- bantu sekali per query, dan mindmg terakhir karena syaratnya membacanya.
UPDATE `creature_template` `ct`
JOIN `prabowow_hyjal_new_templates` `new` ON `new`.`entry` = `ct`.`entry`
SET `ct`.`attackpower` = COALESCE((
        SELECT `ref`.`attackpower` FROM `prabowow_hyjal_dmg_ref` `ref`
        ORDER BY ABS(`ref`.`minlevel` - `ct`.`minlevel`),
                 `ref`.`npc_rank` = `ct`.`npc_rank` DESC
        LIMIT 1), 1)
WHERE `ct`.`attackpower` = 0;

UPDATE `creature_template` `ct`
JOIN `prabowow_hyjal_new_templates` `new` ON `new`.`entry` = `ct`.`entry`
SET `ct`.`maxdmg` = COALESCE((
        SELECT `ref`.`maxdmg` FROM `prabowow_hyjal_dmg_ref` `ref`
        ORDER BY ABS(`ref`.`minlevel` - `ct`.`minlevel`),
                 `ref`.`npc_rank` = `ct`.`npc_rank` DESC
        LIMIT 1), 1)
WHERE `ct`.`maxdmg` = 0;

UPDATE `creature_template` `ct`
JOIN `prabowow_hyjal_new_templates` `new` ON `new`.`entry` = `ct`.`entry`
SET `ct`.`mindmg` = COALESCE((
        SELECT `ref`.`mindmg` FROM `prabowow_hyjal_dmg_ref` `ref`
        ORDER BY ABS(`ref`.`minlevel` - `ct`.`minlevel`),
                 `ref`.`npc_rank` = `ct`.`npc_rank` DESC
        LIMIT 1), 1)
WHERE `ct`.`mindmg` = 0;

DROP TABLE IF EXISTS `prabowow_hyjal_dmg_ref`;
DROP TABLE IF EXISTS `prabowow_hyjal_new_templates`;

